import re
from typing import Callable

def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    # Parse cell names like "A12" into (col, row) where col is 0-25, row is 1-99
    def parse_cell(name: str) -> tuple[int, int]:
        col = ord(name[0]) - ord('A')
        row = int(name[1:])
        return (col, row)

    # Parse a range like "A1:B3" into corners, sorted properly
    def parse_range(rng: str) -> tuple[tuple[int, int], tuple[int, int]]:
        parts = rng.split(':')
        c1, r1 = parse_cell(parts[0])
        c2, r2 = parse_cell(parts[1])
        return ((min(c1, c2), min(r1, r2)), (max(c1, c2), max(r1, r2)))

    # Get all cell names in a range, in row-major order
    def range_cells(rng: str) -> list[str]:
        (c1, r1), (c2, r2) = parse_range(rng)
        result = []
        for row in range(r1, r2 + 1):
            for col in range(c1, c2 + 1):
                result.append(chr(ord('A') + col) + str(row))
        return result

    # Tokenize a formula string
    def tokenize(formula: str) -> list[str]:
        # Remove leading '='
        if formula.startswith('='):
            formula = formula[1:]
        # Remove spaces
        formula = formula.replace(' ', '')
        tokens = []
        i = 0
        while i < len(formula):
            if formula[i] in '+-*/()=<>,':
                # Check for two-character operators like '<=', '>=', '<>'
                if i + 1 < len(formula) and formula[i:i+2] in ('<=', '>=', '<>'):
                    tokens.append(formula[i:i+2])
                    i += 2
                else:
                    tokens.append(formula[i])
                    i += 1
            elif formula[i].isalpha():
                # Cell name or function
                start = i
                while i < len(formula) and (formula[i].isalpha() or formula[i].isdigit()):
                    i += 1
                tokens.append(formula[start:i])
            elif formula[i].isdigit():
                # Number
                start = i
                while i < len(formula) and formula[i].isdigit():
                    i += 1
                tokens.append(formula[start:i])
            else:
                i += 1
        return tokens

    # Parse tokens into an AST using recursive descent
    def parse_expression(tokens: list[str], pos: int) -> tuple[dict, int]:
        # Parse addition/subtraction (lowest precedence)
        node, pos = parse_term(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_term(tokens, pos)
            node = {'type': 'binop', 'op': op, 'left': node, 'right': right}
        return node, pos

    def parse_term(tokens: list[str], pos: int) -> tuple[dict, int]:
        # Parse multiplication/division
        node, pos = parse_unary(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_unary(tokens, pos)
            node = {'type': 'binop', 'op': op, 'left': node, 'right': right}
        return node, pos

    def parse_unary(tokens: list[str], pos: int) -> tuple[dict, int]:
        # Parse unary minus (can repeat)
        count = 0
        while pos < len(tokens) and tokens[pos] == '-':
            count += 1
            pos += 1
        node, pos = parse_atom(tokens, pos)
        for _ in range(count):
            node = {'type': 'unary', 'op': '-', 'arg': node}
        return node, pos

    def parse_atom(tokens: list[str], pos: int) -> tuple[dict, int]:
        if pos >= len(tokens):
            return {'type': 'error'}, pos

        if tokens[pos] == '(':
            pos += 1
            node, pos = parse_expression(tokens, pos)
            if pos < len(tokens) and tokens[pos] == ')':
                pos += 1
            return node, pos

        if tokens[pos].isdigit():
            node = {'type': 'number', 'value': int(tokens[pos])}
            pos += 1
            return node, pos

        if tokens[pos][0].isalpha():
            # Check if it's a function call
            if pos + 1 < len(tokens) and tokens[pos + 1] == '(':
                func = tokens[pos]
                pos += 2  # skip function name and '('
                args = []
                while pos < len(tokens) and tokens[pos] != ')':
                    arg, pos = parse_arg(tokens, pos)
                    args.append(arg)
                    if pos < len(tokens) and tokens[pos] == ',':
                        pos += 1
                if pos < len(tokens) and tokens[pos] == ')':
                    pos += 1
                return {'type': 'function', 'name': func, 'args': args}, pos
            else:
                # Cell reference
                return {'type': 'cell', 'name': tokens[pos]}, pos + 1

        return {'type': 'error'}, pos

    def parse_arg(tokens: list[str], pos: int) -> tuple[dict, int]:
        # Parse an argument which could be a range or a formula
        # Look ahead to see if it's a range (cell:cell)
        start = pos
        # Try to parse as a cell name
        if pos < len(tokens) and tokens[pos][0].isalpha():
            cell1 = tokens[pos]
            pos += 1
            if pos < len(tokens) and tokens[pos] == ':':
                pos += 1
                if pos < len(tokens) and tokens[pos][0].isalpha():
                    cell2 = tokens[pos]
                    pos += 1
                    return {'type': 'range', 'value': cell1 + ':' + cell2}, pos
            # Not a range, backtrack
            pos = start
        return parse_expression(tokens, pos)

    # Evaluation
    values: dict[str, int | str] = {}
    evaluating: set[str] = set()

    def evaluate_cell(name: str) -> int | str:
        if name in values:
            return values[name]
        if name in evaluating:
            return "#CYCLE!"

        evaluating.add(name)

        if name not in cells:
            evaluating.remove(name)
            values[name] = 0
            return 0

        content = cells[name]

        if not content.startswith('='):
            # Integer literal
            try:
                result = int(content)
            except ValueError:
                result = 0
            evaluating.remove(name)
            values[name] = result
            return result

        # Formula
        tokens = tokenize(content)
        ast, _ = parse_expression(tokens, 0)
        result = evaluate(ast)

        evaluating.remove(name)
        values[name] = result
        return result

    def evaluate(node: dict) -> int | str:
        if node['type'] == 'number':
            return node['value']

        if node['type'] == 'cell':
            return evaluate_cell(node['name'])

        if node['type'] == 'unary':
            if node['op'] == '-':
                val = evaluate(node['arg'])
                if isinstance(val, str):
                    return val
                return -val

        if node['type'] == 'binop':
            left = evaluate(node['left'])
            if isinstance(left, str):
                return left
            right = evaluate(node['right'])
            if isinstance(right, str):
                return right

            if node['op'] == '+':
                return left + right
            elif node['op'] == '-':
                return left - right
            elif node['op'] == '*':
                return left * right
            elif node['op'] == '/':
                if right == 0:
                    return "#DIV/0!"
                # Truncate toward zero
                return int(left / right)

        if node['type'] == 'function':
            name = node['name']
            args = node['args']

            if name in ('SUM', 'MIN', 'MAX'):
                # Evaluate arguments left to right
                values_list = []
                for arg in args:
                    if arg['type'] == 'range':
                        # Get cells in range, evaluate those that exist in cells dict
                        for cell_name in range_cells(arg['value']):
                            if cell_name in cells:
                                val = evaluate_cell(cell_name)
                                if isinstance(val, str):
                                    return val
                                values_list.append(val)
                    else:
                        val = evaluate(arg)
                        if isinstance(val, str):
                            return val
                        values_list.append(val)

                if not values_list:
                    return 0

                if name == 'SUM':
                    return sum(values_list)
                elif name == 'MIN':
                    return min(values_list)
                elif name == 'MAX':
                    return max(values_list)

            elif name == 'IF':
                # IF(left OP right, then, else)
                if len(args) != 4:
                    return "#DIV/0!"

                left = evaluate(args[0])
                if isinstance(left, str):
                    return left

                right = evaluate(args[1])
                if isinstance(right, str):
                    return right

                op = args[2]
                # op should be a token from parsing
                op_val = op if isinstance(op, str) else op.get('value', '=')

                condition = False
                if op_val == '=':
                    condition = left == right
                elif op_val == '<>':
                    condition = left != right
                elif op_val == '<':
                    condition = left < right
                elif op_val == '<=':
                    condition = left <= right
                elif op_val == '>':
                    condition = left > right
                elif op_val == '>=':
                    condition = left >= right

                if condition:
                    return evaluate(args[3])
                else:
                    return evaluate(args[4])

        return 0

    # Evaluate all cells
    for name in cells:
        if name not in values:
            evaluate_cell(name)

    return values
